#include <iostream>
#include <stdexcept>
using namespace std;

double divide(double a, double b) {
    if (b == 0)
        throw invalid_argument("Division by zero!");
    return a / b;
}

int main() {
    try {
        cout << divide(10, 0);
    } catch (const exception& e) {
        cout << "Error: " << e.what() << endl;
    }
    return 0;
}

